def normalize_path(path: str) -> str:
    """
    Normalize a Unix-style POSIX path string by resolving '.' and '..'
    components and collapsing redundant separators.

    Does not use os.path.normpath, pathlib, or posixpath.
    """
    if not path:
        return "."

    is_absolute = path.startswith("/")

    # Split on '/' and filter out empty strings and '.' components
    parts = path.split("/")

    stack = []

    for part in parts:
        if part == "" or part == ".":
            # Skip empty parts (from multiple slashes or trailing slash) and '.'
            continue
        elif part == "..":
            if is_absolute:
                # In absolute path, '..' at root stays at root
                if stack:
                    stack.pop()
                # else: already at root, do nothing
            else:
                # In relative path, if stack has a real component (not '..'), pop it
                if stack and stack[-1] != "..":
                    stack.pop()
                else:
                    # Preserve leading '..' components
                    stack.append("..")
        else:
            stack.append(part)

    if is_absolute:
        return "/" + "/".join(stack)
    else:
        result = "/".join(stack)
        return result if result else "."
